  selectedCustomerId: string | null
  onSelect: (customerId: string | null) => void
}) {
  const [customers, setCustomers] = useState<QuoteCustomer[]>([])
  const [searchTerm, setSearchTerm] = useState('')
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (!isOpen) return

    async function fetchCustomers() {
      setLoading(true)
      try {
        // Fetch customers from API with optional search filter
        const params = new URLSearchParams({ limit: '50' })
        if (searchTerm) params.set('search', searchTerm)

        const response = await fetch(`/api/customers?${params.toString()}`)
        if (!response.ok) throw new Error('Failed to fetch customers')

        const data = await response.json() as { items: QuoteCustomer[]; total: number }
        setCustomers(data.items ?? [])
      } catch (err) {
        console.error('[CreateQuoteForm] Failed to load customers:', err)
        setCustomers([])
      } finally {
        setLoading(false)
      }
    }

    fetchCustomers()
  }, [searchTerm]) // Re-fetch when search term changes

  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-gray-700">Customer</label>

